`substitutionSpanEnd` decomposition — CAREFUL. This is a recursive/loop-carrying rewrite:

OLD:
```dart
int substitutionSpanEnd(String input, int start) {
 if (input[start] == '`') return _backquoteSpanEnd(input, start);
 var depth = 1;
 var i = start + 2;
 while (i < input.length) {
   final ch = input[i];
   if (ch == '\\') { i += 2; continue; }
   if (ch == "'" || ch == '"') { i = _quotedSpanEnd(input, i, ch); if (i == -1) return -1; continue; }
   if (ch == '`') { i = _backquoteSpanEnd(input, i); if (i == -1) return -1; continue; }
   if (ch == '\$' && i + 1 < input.length && input[i + 1] == '(') { depth++; i += 2; continue; }
   if (ch == ') { depth--; i++; if (depth == 0) return i; continue; }
   i++;
 }
 return -1;
}
```

NEW:
```dart
int substitutionSpanEnd(String input, int start) {
 if (input[start] == '`') return _backquoteSpanEnd(input, start);
 return _substitutionParenEnd(input, start + 2, 1);
}

int _substitutionParenEnd(String input, int start, int depth) {
 var i = start;
 while (i < input.length) {
   if (input[i] == ') {
     i++;
     if (--depth == 0) return i;
     continue;
   }
   final (next, opened) = _substitutionSkip(input, i);
   if (next == -1) return -1;
   i = next;
   depth += opened;
 }
 return -1;
}
```

