List<_Token> _tokenize(String input) {
  final state = _TokenizerState(input);
  var i = 0;
  while (i < input.length) {
    i = state.step(i);
  }
  state.flushWord();
  state.throwIfUnterminatedHeredoc();
  return state.tokens;
}

