  List<_DiffOp> ops,
  List<String> oldTokens,
  List<String> newTokens, {
  required String oldLabel,
  required String newLabel,
  required int context,
}) {
  final out = StringBuffer()
    ..writeln('--- $oldLabel')
    ..writeln('+++ $newLabel');
  var i = 0;
